-- 外研社七上 wy7A 听力灌库(junior_listening_exercises)· publisher=junior_fltrp · volume=wy7A · grade=7 · 7单元×6篇=42
-- 体裁:3对话+2独白(passage)+1通知(notice)/单元 · 每篇2题(1细节+1主旨/推断)4选1 · UK英音单音色(speaker=fable)
-- audio_url 先 NULL,跑 scripts/gen-fltrp-listening-audio.mjs(UK/fable/0.85)后由 wy7a-listening-audio-url.sql 回填
-- ★DELETE 带 publisher='junior_fltrp' AND volume='wy7A' 双限,绝不动人教/其他册★
BEGIN;
DELETE FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy7A';
INSERT INTO public.junior_listening_exercises
  (id, grade, publisher, volume, unit, title, topic, transcript, translation_cn, audio_url, speaker, kind, duration_sec, difficulty, questions, key_vocab) VALUES
  ('75bc7345-cf6c-61ad-ccb1-b4619063ac1c', 7, 'junior_fltrp', 'wy7A', 'Starter', 'Nice to meet you', '新同学互相介绍', 'A: Hi! I''m Ben. Are you a new student too?
B: Yes, I am. My name is Lily. Nice to meet you, Ben.
A: Nice to meet you too, Lily. Which class are you in?
B: I''m in Class Three. What about you?
A: Oh, me too! We''re classmates then. Where are you from?
B: I''m from Beijing. Well, my family lives here now.', 'A:嗨!我是Ben。你也是新生吗?B:是的。我叫Lily,很高兴认识你。A:我也很高兴认识你。你在哪个班?B:三班,你呢?A:哦,我也是!那我们是同学了。你从哪儿来?B:北京,不过我家现在住这儿。', NULL, 'fable', 'dialogue', 34, 1, '[{"type": "choice", "q": "What class is Lily in?", "options": ["Class Three.", "Class One.", "Class Two.", "Class Four."], "answer": "A", "explanation": "Lily 说 ''I''m in Class Three.''"}, {"type": "choice", "q": "What do Ben and Lily find out at the end?", "options": ["They live in the same house.", "They like the same sport.", "They have the same teacher.", "They are in the same class."], "answer": "D", "explanation": "Ben 说 ''me too... We''re classmates then.''"}]'::jsonb, '[{"word": "Beijing", "cn": "北京"}]'::jsonb),
  ('efe3476e-9a61-57b5-a9f9-c3fda2c4f081', 7, 'junior_fltrp', 'wy7A', 'Starter', 'My favourite subject', '问最喜欢的科目', 'A: Hey Sam, what''s your favourite subject?
B: I like English best. It''s fun, and our teacher is very kind.
A: Really? I''m not good at English. I like maths more.
B: Maths? Oh, it''s too hard for me!
A: Well, I can help you with maths, and you can help me with English.
B: That''s a great idea. Thanks, Kate!', 'A:嘿Sam,你最喜欢什么科目?B:我最喜欢英语,很有趣,老师也很好。A:真的?我英语不好,我更喜欢数学。B:数学?对我太难了!A:那我帮你数学,你帮我英语。B:好主意,谢谢Kate!', NULL, 'fable', 'dialogue', 33, 1, '[{"type": "choice", "q": "What subject does Sam like best?", "options": ["Maths.", "Music.", "English.", "Art."], "answer": "C", "explanation": "Sam 说 ''I like English best.''"}, {"type": "choice", "q": "What do the two friends decide to do?", "options": ["Play maths games together.", "Help each other with their subjects.", "Ask the teacher for help.", "Stop studying English."], "answer": "B", "explanation": "结尾两人约定互相帮助各自的科目。"}]'::jsonb, '[{"word": "favourite", "cn": "最喜欢的"}, {"word": "idea", "cn": "主意,想法"}]'::jsonb),
  ('2b47c19a-a773-0988-2597-78ae0d5de0d3', 7, 'junior_fltrp', 'wy7A', 'Starter', 'Our new classroom', '教室物品·there be', 'A: Wow, our new classroom is so big and clean!
B: Yes! There are forty desks and a big blackboard.
A: Look, there is a bookshelf near the window.
B: And there are some nice green plants on it.
A: I really like our new classroom.
B: Me too. Everything here is new.', 'A:哇,我们的新教室又大又干净!B:是啊!有四十张课桌和一块大黑板。A:看,窗边有个书架。B:上面还有些好看的绿植。A:我真喜欢我们的新教室。B:我也是,这里一切都是新的。', NULL, 'fable', 'dialogue', 26, 1, '[{"type": "choice", "q": "How many desks are there in the classroom?", "options": ["Forty.", "Twenty.", "Thirty.", "Fifty."], "answer": "A", "explanation": "''There are forty desks.''"}, {"type": "choice", "q": "How do the two students feel about their new classroom?", "options": ["They think it is too small.", "They find it old and dirty.", "They like it very much.", "They do not like it."], "answer": "C", "explanation": "''I really like our new classroom.'' / ''Me too.''"}]'::jsonb, '[{"word": "blackboard", "cn": "黑板"}, {"word": "bookshelf", "cn": "书架"}]'::jsonb),
  ('3815fda0-aab7-efe7-b9ab-b3be3e654bd3', 7, 'junior_fltrp', 'wy7A', 'Starter', 'My new school', '独白·介绍新学校', 'Hello, everyone. My name is Anna. I am twelve years old, and this is my first week at junior high school. My school is big and clean. There are two playgrounds and a large library. My classroom is on the second floor, and my desk is near the window. My new classmates are friendly, and my teachers are kind. I like the art club best. We meet every Friday afternoon. I am very happy here. I really like my new school.', '大家好,我叫Anna,十二岁,这是我上初中的第一周。我的学校又大又干净,有两个操场和一个大图书馆。我的教室在二楼,课桌靠窗。新同学很友好,老师很和蔼。我最喜欢美术社团,每周五下午活动。我在这儿很开心,真的很喜欢我的新学校。', NULL, 'fable', 'passage', 44, 1, '[{"type": "choice", "q": "When does the art club meet?", "options": ["Every Monday.", "Every Wednesday.", "Every weekend.", "Every Friday afternoon."], "answer": "D", "explanation": "''We meet every Friday afternoon.''"}, {"type": "choice", "q": "How does Anna feel about her new school?", "options": ["Bored and tired.", "Happy and pleased.", "Sad and lonely.", "Afraid and worried."], "answer": "B", "explanation": "''I am very happy here. I really like my new school.''"}]'::jsonb, '[{"word": "playground", "cn": "操场"}]'::jsonb),
  ('472994bb-05f5-4268-3cbe-3a4262cb716a', 7, 'junior_fltrp', 'wy7A', 'Starter', 'This is my family', '独白·介绍家庭', 'Let me tell you about my family. There are four people in it: my dad, my mum, my little brother and me. My dad is a doctor. He is tall and kind. My mum is an English teacher. She is very patient and sings well. My little brother is only five. He is funny and likes to play football with me. We often have dinner together, and we talk about our day. I love my family very much.', '我来介绍我的家。家里有四口人:爸爸、妈妈、小弟弟和我。爸爸是医生,又高又善良。妈妈是英语老师,很有耐心,唱歌好听。小弟弟才五岁,很有趣,喜欢和我踢足球。我们常一起吃晚饭,聊一天的事。我很爱我的家。', NULL, 'fable', 'passage', 43, 2, '[{"type": "choice", "q": "What is Anna''s mum''s job?", "options": ["An English teacher.", "A doctor.", "A singer.", "A football player."], "answer": "A", "explanation": "''My mum is an English teacher.''"}, {"type": "choice", "q": "What can we learn about the family?", "options": ["They live far apart.", "They never eat together.", "They are close and loving.", "They do not talk much."], "answer": "C", "explanation": "常一起吃饭聊天、''I love my family'' → 亲密有爱。"}]'::jsonb, '[{"word": "doctor", "cn": "医生"}, {"word": "patient", "cn": "有耐心的"}]'::jsonb),
  ('6a176dad-f580-ddc4-04da-c20c16a5e018', 7, 'junior_fltrp', 'wy7A', 'Starter', 'Welcome meeting', '通知·迎新社团会', 'Good morning, students. Welcome to Green Hill Junior High School. Here is some news for all new students. There is a welcome meeting this afternoon at three o''clock. It is in the school hall on the first floor. At the meeting, you can learn about our clubs: the music club, the art club and the science club. Please come and join us. See you there!', '同学们早上好。欢迎来到青山初级中学。给全体新生一则通知:今天下午三点有一场迎新会,地点在一楼学校礼堂。会上你可以了解我们的社团:音乐社、美术社和科学社。请来参加,到时见!', NULL, 'fable', 'notice', 36, 1, '[{"type": "choice", "q": "Where is the welcome meeting?", "options": ["In the library.", "On the playground.", "In the art room.", "In the school hall on the first floor."], "answer": "D", "explanation": "''It is in the school hall on the first floor.''"}, {"type": "choice", "q": "What is the notice mainly about?", "options": ["A new library.", "A welcome meeting for new students.", "A sports match.", "An art lesson."], "answer": "B", "explanation": "通知主体=迎新会。"}]'::jsonb, '[{"word": "hall", "cn": "礼堂,大厅"}]'::jsonb),
  ('cadf0a67-91e7-bb99-1f85-b88a41fa7241', 7, 'junior_fltrp', 'wy7A', 'U1', 'Our new timetable', '谈新课程表', 'A: Look, Lucy. Here is our new timetable.
B: Let me see. We have English and maths on Monday morning.
A: Right. And my favourite, art, is on Tuesday.
B: Oh, I love art too! Do we have sport this week?
A: Yes, we do. It''s on Friday afternoon.
B: Great! Friday is my lucky day.', 'A:看,Lucy,这是我们的新课程表。B:我看看。周一上午有英语和数学。A:对,我最喜欢的美术在周二。B:哦我也爱美术!这周有体育吗?A:有,周五下午。B:太好了!周五是我的幸运日。', NULL, 'fable', 'dialogue', 28, 1, '[{"type": "choice", "q": "When do they have sport?", "options": ["On Friday afternoon.", "On Monday.", "On Tuesday.", "On Wednesday."], "answer": "A", "explanation": "''It''s on Friday afternoon.''"}, {"type": "choice", "q": "What are the two students talking about?", "options": ["Their homework.", "Their new timetable.", "A school trip.", "Their teachers."], "answer": "B", "explanation": "全程在看新课程表。"}]'::jsonb, '[{"word": "timetable", "cn": "课程表"}, {"word": "lucky", "cn": "幸运的"}]'::jsonb),
  ('ae937365-7245-138d-424f-7042515c72f6', 7, 'junior_fltrp', 'wy7A', 'U1', 'Is this your pen?', '物主代词·认领物品', 'A: Excuse me, is this your pen?
B: No, it isn''t mine. Mine is blue. This one is black.
A: Maybe it''s Tom''s. His pen is black too.
B: Let''s ask him. Tom, is this pen yours?
C: Oh yes, it''s mine! Thank you. I always look for it everywhere.
B: You''re welcome. Please keep it in your bag next time.', 'A:打扰下,这是你的笔吗?B:不,不是我的,我的是蓝色,这支黑的。A:也许是Tom的,他的笔也是黑的。B:问问他。Tom,这笔是你的吗?C:哦是的,是我的!谢谢,我总是到处找它。B:不客气,下次放包里吧。', NULL, 'fable', 'dialogue', 33, 1, '[{"type": "choice", "q": "What colour is the pen?", "options": ["Blue.", "Red.", "Black.", "Green."], "answer": "C", "explanation": "''This one is black'' / ''His pen is black too.''"}, {"type": "choice", "q": "Whose pen is it?", "options": ["Lucy''s.", "The speaker''s.", "The teacher''s.", "Tom''s."], "answer": "D", "explanation": "Tom 说 ''it''s mine''。"}]'::jsonb, '[{"word": "mine", "cn": "我的(东西)"}, {"word": "everywhere", "cn": "到处"}]'::jsonb),
  ('184aaf35-7805-2d42-11f7-9d5900ef7052', 7, 'junior_fltrp', 'wy7A', 'U1', 'My morning', '日常作息', 'A: You look tired, Ben. What time do you get up?
B: I get up at six thirty. Then I read English for twenty minutes.
A: Wow, so early! What about breakfast?
B: I have breakfast at seven, and I go to school at seven forty.
A: No wonder you''re tired. You should go to bed earlier.
B: Well, you''re right. I''ll try tonight.', 'A:你看起来累,Ben,你几点起床?B:六点半,然后读二十分钟英语。A:哇好早!早饭呢?B:七点吃早饭,七点四十上学。A:难怪你累,你该早点睡。B:嗯你说得对,今晚我试试。', NULL, 'fable', 'dialogue', 33, 2, '[{"type": "choice", "q": "What time does Ben get up?", "options": ["At seven.", "At seven forty.", "At six thirty.", "At six."], "answer": "C", "explanation": "''I get up at six thirty.''"}, {"type": "choice", "q": "Why does Ben look tired?", "options": ["He is ill.", "He gets up very early and goes to bed late.", "He has too much homework.", "He does not like school."], "answer": "B", "explanation": "起太早、被劝早睡 → 睡太晚起太早。"}]'::jsonb, '[{"word": "early", "cn": "早地"}, {"word": "tonight", "cn": "今晚"}]'::jsonb),
  ('7c761a67-d742-ba9e-3e01-72bffcbec87b', 7, 'junior_fltrp', 'wy7A', 'U1', 'My first week', '独白·初中第一周', 'Hi, I''m Jack. This is my first week at junior high school, and everything is new to me. I have seven subjects now, and I really like science. My new classmates are friendly, and we help each other. Every morning I get up early and go to school by bike. After class, I often play football with my friends. There is so much to do here. I think junior high is a great new start for me.', '嗨,我是Jack。这是我上初中第一周,一切都新鲜。我现在有七门课,我很喜欢科学。新同学友好,我们互相帮助。每天早上我早起骑车上学。放学后常和朋友踢球。这里有好多事可做。我觉得初中对我是个很棒的新开始。', NULL, 'fable', 'passage', 43, 1, '[{"type": "choice", "q": "How does Jack go to school?", "options": ["On foot.", "By bus.", "By car.", "By bike."], "answer": "D", "explanation": "''go to school by bike.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["Jack''s first week at junior high.", "Jack''s football team.", "Jack''s science teacher.", "Jack''s family."], "answer": "A", "explanation": "全文讲Jack初中第一周。"}]'::jsonb, '[{"word": "bike", "cn": "自行车"}]'::jsonb),
  ('326846b9-3299-4d39-0a73-934f550e882a', 7, 'junior_fltrp', 'wy7A', 'U1', 'A day at school', '独白·校园一天', 'My name is Emma, and I want to tell you about my school day. Our first class starts at eight o''clock. In the morning we have four lessons. My favourite is English, because our teacher is funny and kind. At twelve we have lunch in the school dining hall. In the afternoon we have two more lessons and then club time. I am in the art club. School is busy, but I enjoy every day.', '我叫Emma,给你讲讲我的校园一天。第一节课八点开始。上午四节课,我最喜欢英语,因为老师风趣和蔼。十二点在学校餐厅吃午饭。下午两节课,然后是社团时间。我在美术社。学校很忙,但我享受每一天。', NULL, 'fable', 'passage', 41, 2, '[{"type": "choice", "q": "How many lessons does Emma have in the morning?", "options": ["Two.", "Three.", "Four.", "Five."], "answer": "C", "explanation": "''In the morning we have four lessons.''"}, {"type": "choice", "q": "How does Emma feel about her school life?", "options": ["Busy but happy.", "Boring and tired.", "Sad and lonely.", "Angry and afraid."], "answer": "A", "explanation": "''busy, but I enjoy every day.''"}]'::jsonb, '[{"word": "lunch", "cn": "午饭"}, {"word": "enjoy", "cn": "享受,喜爱"}]'::jsonb),
  ('5dcb4086-919f-fbd1-072f-7b9d78e498a2', 7, 'junior_fltrp', 'wy7A', 'U1', 'Club sign-up', '通知·社团报名', 'Attention, please. Here is some news for all new students. This Friday afternoon, you can sign up for your school clubs. We have a music club, an art club, a sports club and a reading club. Each student can join one club. Please come to the school hall at four o''clock and write down your name. Have a great new start!', '请注意,给全体新生的通知。本周五下午可以报名社团。我们有音乐社、美术社、运动社和阅读社。每人可加入一个社团。请四点到学校礼堂写下名字。祝你有个美好的新开始!', NULL, 'fable', 'notice', 34, 1, '[{"type": "choice", "q": "How many clubs can each student join?", "options": ["Two.", "Three.", "Four.", "One."], "answer": "D", "explanation": "''Each student can join one club.''"}, {"type": "choice", "q": "What is the notice about?", "options": ["A sports match.", "Signing up for school clubs.", "A new timetable.", "A school trip."], "answer": "B", "explanation": "通知主体=社团报名。"}]'::jsonb, '[{"word": "sign up", "cn": "报名"}, {"word": "attention", "cn": "注意"}]'::jsonb),
  ('98118e78-1c45-e0d8-6174-8bfcbf60332a', 7, 'junior_fltrp', 'wy7A', 'U2', 'What do you do after school?', '课余爱好', 'A: What do you usually do after school, Kate?
B: I often draw pictures at home. I love art. What about you, Sam?
A: I play basketball with my friends. We practise every day.
B: That sounds fun. Do you play well?
A: Not really, but I enjoy it a lot.
B: Well, having fun is the most important thing.', 'A:Kate,你放学后常做什么?B:我常在家画画,我爱美术。你呢Sam?A:我和朋友打篮球,每天练。B:听着有趣,你打得好吗?A:不太好,但我很享受。B:嗯,开心最重要。', NULL, 'fable', 'dialogue', 29, 1, '[{"type": "choice", "q": "What does Kate often do after school?", "options": ["Play basketball.", "Read books.", "Sing songs.", "Draw pictures."], "answer": "D", "explanation": "''I often draw pictures at home.''"}, {"type": "choice", "q": "What idea do they agree on?", "options": ["Having fun matters most.", "Basketball is the best sport.", "Art is easy.", "You must play well."], "answer": "A", "explanation": "结尾 ''having fun is the most important thing.''"}]'::jsonb, '[{"word": "draw", "cn": "画画"}, {"word": "practise", "cn": "练习"}]'::jsonb),
  ('0958781a-f12d-b8f7-ff02-386c4cab82cd', 7, 'junior_fltrp', 'wy7A', 'U2', 'Join our club', '邀请加入社团', 'A: Hi Lily, do you want to join the music club?
B: Maybe. What do you do in the club?
A: We sing songs and play the guitar every Wednesday.
B: That sounds nice, but I can''t play any instrument.
A: Don''t worry. You can learn. We help each other.
B: OK then. I''ll come this Wednesday. Thank you!', 'A:嗨Lily,想加入音乐社吗?B:也许吧,社里做什么?A:每周三唱歌、弹吉他。B:听着不错,但我不会任何乐器。A:别担心,你可以学,我们互相帮助。B:那好,这周三我来,谢谢!', NULL, 'fable', 'dialogue', 31, 2, '[{"type": "choice", "q": "When does the music club meet?", "options": ["On Monday.", "On Tuesday.", "On Wednesday.", "On Sunday."], "answer": "C", "explanation": "''every Wednesday.''"}, {"type": "choice", "q": "Why does Lily decide to join?", "options": ["She plays the guitar well.", "The others will help her learn.", "She has nothing to do.", "Her friend is the teacher."], "answer": "B", "explanation": "''You can learn. We help each other.'' → 因有人帮学。"}]'::jsonb, '[{"word": "guitar", "cn": "吉他"}, {"word": "instrument", "cn": "乐器"}]'::jsonb),
  ('2df830ce-d9f5-66c0-a156-f9fca78db1af', 7, 'junior_fltrp', 'wy7A', 'U2', 'My weekend', '谈周末活动', 'A: What do you do at weekends, Mike?
B: On Saturday I help my mum at home. On Sunday I go swimming.
A: Do you like swimming?
B: Yes, I love it. It makes me strong and happy.
A: Can I come with you next Sunday?
B: Of course! Let''s go together.', 'A:Mike,你周末做什么?B:周六帮妈妈做家务,周日去游泳。A:你喜欢游泳吗?B:是的,我爱游泳,它让我强壮又开心。A:下周日我能一起去吗?B:当然!一起去。', NULL, 'fable', 'dialogue', 26, 1, '[{"type": "choice", "q": "What does Mike do on Sunday?", "options": ["He helps his mum.", "He plays football.", "He goes swimming.", "He reads books."], "answer": "C", "explanation": "''On Sunday I go swimming.''"}, {"type": "choice", "q": "Why does Mike like swimming?", "options": ["It makes him strong and happy.", "It is easy.", "His friends do it.", "It is free."], "answer": "A", "explanation": "''It makes me strong and happy.''"}]'::jsonb, '[{"word": "swimming", "cn": "游泳"}]'::jsonb),
  ('b2854b79-bbe1-d3fc-eb78-0a233ad62fe4', 7, 'junior_fltrp', 'wy7A', 'U2', 'My hobby', '独白·我的爱好', 'Hello, I''m Lucy. I have an interesting hobby. I collect stamps from many countries. My father gives me his old stamps, and I keep them in a big book. Each stamp tells a little story. Some show animals, and some show famous places. I look at them every evening. Collecting stamps is more than fun. It also helps me learn about the world.', '大家好,我是Lucy。我有个有趣的爱好——集邮,收集许多国家的邮票。爸爸把旧邮票给我,我把它们放在一个大本子里。每张邮票都讲个小故事,有的画动物,有的画名胜。我每晚看它们。集邮不只是乐趣,还帮我了解世界。', NULL, 'fable', 'passage', 35, 1, '[{"type": "choice", "q": "What does Lucy collect?", "options": ["Old books.", "Coins.", "Photos.", "Stamps."], "answer": "D", "explanation": "''I collect stamps.''"}, {"type": "choice", "q": "Why is Lucy''s hobby ''more than fun''?", "options": ["It makes money.", "It helps her learn about the world.", "It is very easy.", "It needs no time."], "answer": "B", "explanation": "''It also helps me learn about the world.''"}]'::jsonb, '[{"word": "collect", "cn": "收集"}, {"word": "stamps", "cn": "邮票"}]'::jsonb),
  ('6cdbc98b-744c-3e0c-15d4-99418369008b', 7, 'junior_fltrp', 'wy7A', 'U2', 'The school art show', '独白·校园艺术展', 'Every year our school has an art show, and it is my favourite day. Students bring their best work: paintings, photos and small models. This year I show a picture of my cat. Many people like it, and I feel proud. My friend Ben plays the guitar on the stage, and everyone claps. The art show is not just for fun. It helps us share what we love and make new friends.', '每年学校有艺术展,那是我最喜欢的日子。学生带来最好的作品:画、照片和小模型。今年我展出一幅我猫的画,很多人喜欢,我很自豪。朋友Ben在台上弹吉他,大家鼓掌。艺术展不只是玩,它帮我们分享所爱、结交新朋友。', NULL, 'fable', 'passage', 39, 2, '[{"type": "choice", "q": "What does the writer show this year?", "options": ["A photo of a dog.", "A small model.", "A song.", "A picture of a cat."], "answer": "D", "explanation": "''a picture of my cat.''"}, {"type": "choice", "q": "What is the main idea of the passage?", "options": ["Art is difficult.", "Ben plays the guitar well.", "The art show lets students share what they love.", "Cats are lovely."], "answer": "C", "explanation": "结尾点题:分享所爱、交朋友。"}]'::jsonb, '[{"word": "proud", "cn": "自豪的"}, {"word": "stage", "cn": "舞台"}]'::jsonb),
  ('f16846ee-8f2e-527f-6735-c9655b33fb31', 7, 'junior_fltrp', 'wy7A', 'U2', 'Sports day', '通知·运动会', 'Good morning, students. Here is some news about our school sports day. It is next Thursday on the school playground. There are many games: running, jumping and football. Each class has a team. Come and cheer for your friends. The sports day starts at nine in the morning. Please wear your sports clothes. Let''s have fun together!', '同学们早上好。关于学校运动会的通知:下周四在学校操场举行。有很多项目:跑步、跳远和足球。每班一队。来为朋友加油。运动会上午九点开始。请穿运动服。让我们一起玩得开心!', NULL, 'fable', 'notice', 32, 1, '[{"type": "choice", "q": "When does the sports day start?", "options": ["At eight.", "At nine in the morning.", "At ten.", "In the afternoon."], "answer": "B", "explanation": "''starts at nine in the morning.''"}, {"type": "choice", "q": "What is the notice mainly about?", "options": ["A school sports day.", "An art show.", "A music club.", "A maths lesson."], "answer": "A", "explanation": "通知主体=运动会。"}]'::jsonb, '[{"word": "cheer", "cn": "欢呼,加油"}, {"word": "jumping", "cn": "跳"}]'::jsonb),
  ('e9e9b12d-4b8f-4796-b237-d0e1ae8aa182', 7, 'junior_fltrp', 'wy7A', 'U3', 'Whose photo is this?', '家庭照片·所有格', 'A: Anna, whose photo is this on your desk?
B: Oh, that''s my family''s photo. This is my mum and dad.
A: Who is the little boy?
B: He''s my brother, Sam. And this old man is my grandpa.
A: Your family looks so happy!
B: Yes, we are. Family is the most important thing to me.', 'A:Anna,你桌上这张照片是谁的?B:哦,那是我家的全家福,这是我爸妈。A:小男孩是谁?B:我弟弟Sam,这位老人是我爷爷。A:你家看着真幸福!B:是的。家人对我最重要。', NULL, 'fable', 'dialogue', 29, 1, '[{"type": "choice", "q": "Who is the little boy in the photo?", "options": ["Anna''s father.", "Anna''s brother.", "Anna''s grandpa.", "Anna''s friend."], "answer": "B", "explanation": "''He''s my brother, Sam.''"}, {"type": "choice", "q": "What does Anna think is most important?", "options": ["Her family.", "Her desk.", "Her photo.", "Her school."], "answer": "A", "explanation": "''Family is the most important thing to me.''"}]'::jsonb, '[{"word": "photo", "cn": "照片"}]'::jsonb),
  ('7edc8104-657a-0951-8801-814a8ad1bce5', 7, 'junior_fltrp', 'wy7A', 'U3', 'Helping at home', '分担家务', 'A: Ben, do you help your parents at home?
B: Yes, I do. I clean my room and wash the dishes.
A: That''s good. I take care of my little sister after school.
B: Really? That''s not easy.
A: It isn''t, but I love her. She is my mum''s little helper too.
B: Your family works together. That''s really nice.', 'A:Ben,你在家帮父母吗?B:帮的,我打扫房间、洗碗。A:真好。我放学后照顾妹妹。B:真的?那不容易。A:是不容易,但我爱她,她也是妈妈的小帮手。B:你们一家人齐心协力,真好。', NULL, 'fable', 'dialogue', 32, 2, '[{"type": "choice", "q": "What does Ben do at home?", "options": ["Cooks dinner.", "Takes care of a baby.", "Cleans his room and washes the dishes.", "Waters the plants."], "answer": "C", "explanation": "''I clean my room and wash the dishes.''"}, {"type": "choice", "q": "What can we learn about the two families?", "options": ["They are very rich.", "They live together.", "They have many pets.", "Everyone helps at home."], "answer": "D", "explanation": "两家孩子都做家务 → 人人帮忙。"}]'::jsonb, '[{"word": "dishes", "cn": "碗碟"}, {"word": "helper", "cn": "帮手"}]'::jsonb),
  ('3dbbaef3-d91a-b6a9-ebbd-787721af9cb9', 7, 'junior_fltrp', 'wy7A', 'U3', 'My father''s job', '谈父母职业', 'A: What does your father do, Lily?
B: He is a doctor. He works at the city hospital.
A: Wow, that''s a great job. Is he busy?
B: Yes, very busy. But he always comes home for dinner.
A: What about your mother?
B: She''s a teacher. She''s kind and patient, just like at home.', 'A:Lily,你爸爸做什么工作?B:他是医生,在市医院工作。A:哇好工作,他忙吗?B:很忙,但他总回家吃晚饭。A:你妈妈呢?B:她是老师,和在家一样和蔼有耐心。', NULL, 'fable', 'dialogue', 28, 1, '[{"type": "choice", "q": "What is Lily''s father''s job?", "options": ["A doctor.", "A teacher.", "A driver.", "A cook."], "answer": "A", "explanation": "''He is a doctor.''"}, {"type": "choice", "q": "What kind of father is he?", "options": ["Lazy and quiet.", "Angry and strict.", "Busy but caring about family.", "Free and rich."], "answer": "C", "explanation": "忙但总回家吃饭 → 忙却顾家。"}]'::jsonb, '[{"word": "hospital", "cn": "医院"}]'::jsonb),
  ('9ad6121f-c6f0-dca5-4926-42e32fad8265', 7, 'junior_fltrp', 'wy7A', 'U3', 'My grandma', '独白·我的奶奶', 'I want to tell you about my grandma. She is seventy years old, but she is still strong and happy. Every morning she waters her flowers in the small garden. She cooks the best noodles in our family. On weekends, she tells me old stories about her life. I love sitting with her. My grandma''s love is warm and quiet, and I feel lucky to have her.', '我想讲讲我奶奶。她七十岁了,但依然强壮开心。每天早上她在小花园浇花。她做的面条是全家最好吃的。周末她给我讲她过去的故事。我爱和她坐在一起。奶奶的爱温暖而安静,有她我觉得很幸运。', NULL, 'fable', 'passage', 37, 1, '[{"type": "choice", "q": "What does grandma do every morning?", "options": ["Cooks noodles.", "Waters her flowers.", "Tells stories.", "Reads books."], "answer": "B", "explanation": "''she waters her flowers.''"}, {"type": "choice", "q": "How does the writer feel about grandma?", "options": ["Bored and tired.", "Afraid and sad.", "Angry and busy.", "Lucky and loving."], "answer": "D", "explanation": "''I feel lucky to have her.''"}]'::jsonb, '[{"word": "garden", "cn": "花园"}, {"word": "noodles", "cn": "面条"}]'::jsonb),
  ('d13072ca-a61d-b357-db5d-57a46db3ce86', 7, 'junior_fltrp', 'wy7A', 'U3', 'Dinner time', '独白·家庭晚餐', 'In my family, dinner time is the best time of the day. At six o''clock, we all sit down together. My mum cooks nice food, and my dad tells us about his day. My sister and I talk about school. We laugh a lot. Sometimes we help clean the table after dinner. It is a simple thing, but sitting together every evening keeps our family close.', '在我家,晚餐是一天中最好的时光。六点我们一起坐下。妈妈做好吃的,爸爸讲他一天的事。我和妹妹聊学校。我们笑个不停。有时饭后一起收拾桌子。这是件简单的事,但每晚一起吃饭让我们一家人亲密。', NULL, 'fable', 'passage', 37, 2, '[{"type": "choice", "q": "What time does the family have dinner?", "options": ["At five.", "At seven.", "At six.", "At eight."], "answer": "C", "explanation": "''At six o''clock, we all sit down together.''"}, {"type": "choice", "q": "What keeps the family close?", "options": ["Nice food.", "A big house.", "Watching TV.", "Sitting together for dinner every evening."], "answer": "D", "explanation": "结尾点题:每晚一起吃饭。"}]'::jsonb, '[{"word": "laugh", "cn": "笑"}]'::jsonb),
  ('de59f951-fd77-d5f6-2945-aae4bd92be27', 7, 'junior_fltrp', 'wy7A', 'U3', 'Family open day', '通知·家庭开放日', 'Dear students, here is some news for you and your families. Next Saturday is our school''s family open day. You can bring your parents to visit our school. They can see your classroom, your art work and your science projects. The open day is from nine to twelve in the morning. We hope to see your families there. Thank you!', '亲爱的同学们,给你和家人的通知:下周六是学校的家庭开放日。你可以带父母参观学校。他们能看你的教室、美术作品和科学项目。开放日上午九点到十二点。希望见到你的家人。谢谢!', NULL, 'fable', 'notice', 33, 1, '[{"type": "choice", "q": "When is the family open day?", "options": ["Next Friday.", "Next Saturday.", "Next Sunday.", "Next Monday."], "answer": "B", "explanation": "''Next Saturday is our school''s family open day.''"}, {"type": "choice", "q": "What is the notice about?", "options": ["A day for families to visit the school.", "A sports day.", "A club meeting.", "A school trip."], "answer": "A", "explanation": "通知主体=家庭开放日。"}]'::jsonb, '[{"word": "visit", "cn": "参观"}, {"word": "projects", "cn": "项目"}]'::jsonb),
  ('eabab832-6fc0-a363-2701-f2d64688b276', 7, 'junior_fltrp', 'wy7A', 'U4', 'How do you spend the festival?', '频率副词·过节习惯', 'A: The Spring Festival is coming. What do you usually do, Lily?
B: We always clean the house first. Then we put red things on the door.
A: Do you often make dumplings?
B: Yes, every year. My grandma and I make them together.
A: That sounds warm. We sometimes visit my uncle in the countryside.
B: Nice! Festivals are always about family.', 'A:春节要到了,Lily你们通常做什么?B:我们总是先打扫房子,然后在门上贴红色的东西。A:你们常包饺子吗?B:是的,每年都包,奶奶和我一起包。A:听着真温馨。我们有时去乡下看叔叔。B:真好!节日总是和家人有关。', NULL, 'fable', 'dialogue', 31, 1, '[{"type": "choice", "q": "What does Lily''s family always do first?", "options": ["Make dumplings.", "Clean the house.", "Visit an uncle.", "Buy new clothes."], "answer": "B", "explanation": "''We always clean the house first.''"}, {"type": "choice", "q": "What do the two friends agree about festivals?", "options": ["They are about food.", "They are about money.", "They are always about family.", "They are about games."], "answer": "C", "explanation": "结尾 ''Festivals are always about family.''"}]'::jsonb, '[{"word": "dumplings", "cn": "饺子"}, {"word": "countryside", "cn": "乡下"}]'::jsonb),
  ('469a90a5-0fb2-8f39-d8fb-659e7448d13e', 7, 'junior_fltrp', 'wy7A', 'U4', 'A gift for Mum', '节日礼物', 'A: Mother''s Day is next Sunday. What will you give your mum?
B: I usually make a card for her. This year I want to do something new.
A: How about cooking her a nice dinner?
B: Good idea! But I never cook. Can you help me?
A: Of course. We can make noodles together. It''s easy.
B: Thank you! Mum will be so happy.', 'A:下周日是母亲节,你要送妈妈什么?B:我通常给她做张卡片,今年想做点新的。A:给她做顿好吃的晚饭怎么样?B:好主意!但我从不做饭,你能帮我吗?A:当然,我们一起做面条,很简单。B:谢谢!妈妈会很开心。', NULL, 'fable', 'dialogue', 33, 2, '[{"type": "choice", "q": "What does the speaker usually make for Mum?", "options": ["Dumplings.", "Noodles.", "A cake.", "A card."], "answer": "D", "explanation": "''I usually make a card for her.''"}, {"type": "choice", "q": "What will the two friends do this year?", "options": ["Cook a dinner for Mum.", "Buy a gift.", "Write a letter.", "Clean the house."], "answer": "A", "explanation": "决定一起做晚饭。"}]'::jsonb, '[{"word": "card", "cn": "卡片"}, {"word": "gift", "cn": "礼物"}]'::jsonb),
  ('3d6768ae-188f-505e-0b7a-bae736863011', 7, 'junior_fltrp', 'wy7A', 'U4', 'The Mid-Autumn night', '中秋赏月', 'A: Look at the moon tonight! It''s so big and round.
B: Yes, it''s the Mid-Autumn Festival. We often sit outside and watch the moon.
A: Do you eat mooncakes too?
B: Of course. My mum always buys my favourite ones.
A: This festival is really nice.
B: It is. Families usually get together on this night.', 'A:看今晚的月亮!又大又圆。B:是啊,中秋节。我们常坐在外面赏月。A:你们也吃月饼吗?B:当然,妈妈总买我最爱吃的。A:这节日真好。B:是的,这一晚家人通常团聚。', NULL, 'fable', 'dialogue', 29, 1, '[{"type": "choice", "q": "What do they often do on this night?", "options": ["Play football.", "Clean the house.", "Sit outside and watch the moon.", "Go to school."], "answer": "C", "explanation": "''we often sit outside and watch the moon.''"}, {"type": "choice", "q": "What is special about the Mid-Autumn Festival?", "options": ["People buy new clothes.", "Families usually get together.", "People go to work.", "People play games."], "answer": "B", "explanation": "结尾 ''Families usually get together on this night.''"}]'::jsonb, '[{"word": "moon", "cn": "月亮"}, {"word": "mooncakes", "cn": "月饼"}]'::jsonb),
  ('719b8931-081e-0f06-f514-a7684efb77b5', 7, 'junior_fltrp', 'wy7A', 'U4', 'My favourite festival', '独白·最爱的节日', 'My favourite festival is the Spring Festival. It always comes in winter. Before the festival, my family usually clean the house together. On New Year''s Eve, we always eat a big dinner. My grandma makes the best dumplings, and we often stay up late. Children usually get red packets from parents. I love this festival because my whole family is always together.', '我最喜欢的节日是春节,它总在冬天到来。节前全家常一起打扫房子。除夕我们总吃一顿丰盛的年夜饭。奶奶包最好吃的饺子,我们常熬到很晚。孩子们通常从父母那里得到红包。我爱这个节日,因为全家人总在一起。', NULL, 'fable', 'passage', 34, 1, '[{"type": "choice", "q": "When does the Spring Festival come?", "options": ["In winter.", "In summer.", "In spring.", "In autumn."], "answer": "A", "explanation": "''It always comes in winter.''"}, {"type": "choice", "q": "Why does the writer love this festival?", "options": ["The food is cheap.", "There is no school.", "It is very short.", "The whole family is always together."], "answer": "D", "explanation": "结尾点题:全家总在一起。"}]'::jsonb, '[{"word": "red packets", "cn": "红包"}, {"word": "eve", "cn": "前夜"}]'::jsonb),
  ('54f88e06-64b2-b14f-471e-4f491cbafb9a', 7, 'junior_fltrp', 'wy7A', 'U4', 'A special birthday', '独白·特别的生日', 'My birthday is always special, and my family never forgets this day. In the morning, my mum always cooks long noodles for good luck. In the evening, my friends often come to my home. We usually play games at parties, so we play and laugh a lot. My dad sometimes gives me a new book. I sometimes get toys too, but the best gift is always my family and friends together.', '我的生日总是很特别,家人从不忘记这天。早上妈妈总煮长寿面讨吉利。晚上朋友们常来我家。我们通常在聚会上玩游戏,又玩又笑。爸爸有时送我一本新书。我有时也收到玩具,但最好的礼物永远是家人和朋友的相聚。', NULL, 'fable', 'passage', 39, 2, '[{"type": "choice", "q": "What does the writer''s mum always cook on the birthday?", "options": ["Dumplings.", "Long noodles.", "A cake.", "Rice."], "answer": "B", "explanation": "''my mum always cooks long noodles for good luck.''"}, {"type": "choice", "q": "What is always the best gift?", "options": ["Family and friends together.", "A new book.", "Some toys.", "A birthday cake."], "answer": "A", "explanation": "''the best gift is always my family and friends together.''"}]'::jsonb, '[{"word": "birthday", "cn": "生日"}, {"word": "toys", "cn": "玩具"}]'::jsonb),
  ('fa5f7cca-06b1-a854-1c10-dad322d2d883', 7, 'junior_fltrp', 'wy7A', 'U4', 'Festival show', '通知·节日晚会', 'Hello, students. Here is some news about our festival show. Next Friday evening, our school will have a show for the Spring Festival. Students will sing, dance and play music on the stage. There will also be nice food to try. The show starts at seven in the evening in the school hall. Bring your family and enjoy the night together!', '同学们好,关于节日晚会的通知:下周五晚上,学校将举办春节晚会。学生们会在台上唱歌、跳舞、演奏音乐。还有好吃的可以尝。晚会晚上七点在学校礼堂开始。带上家人,一起享受这一晚!', NULL, 'fable', 'notice', 33, 1, '[{"type": "choice", "q": "When does the festival show start?", "options": ["At six.", "At eight.", "In the afternoon.", "At seven in the evening."], "answer": "D", "explanation": "''starts at seven in the evening.''"}, {"type": "choice", "q": "What is the notice mainly about?", "options": ["A sports day.", "A club meeting.", "A school show for the Spring Festival.", "A maths test."], "answer": "C", "explanation": "通知主体=节日晚会。"}]'::jsonb, '[{"word": "show", "cn": "演出,晚会"}, {"word": "dance", "cn": "跳舞"}]'::jsonb),
  ('2fb7cd28-c757-f683-c8dd-34dde270a4fa', 7, 'junior_fltrp', 'wy7A', 'U5', 'Our class garden', '将来时·班级花园计划', 'A: Ben, our class is going to make a small garden. Will you help?
B: Sure! What are we going to plant?
A: We''ll plant some flowers and a young tree.
B: Great. The tree will grow tall one day.
A: Yes, and it will give us cool shade in summer.
B: I can''t wait. Let''s start this weekend!', 'A:Ben,我们班要做个小花园,你帮忙吗?B:当然!我们要种什么?A:种些花和一棵小树。B:好,那树将来会长得很高。A:是的,夏天还会给我们凉爽的树荫。B:等不及了,这周末就开始吧!', NULL, 'fable', 'dialogue', 31, 1, '[{"type": "choice", "q": "What are they going to plant?", "options": ["Only flowers.", "Some flowers and a young tree.", "Only a tree.", "Some grass."], "answer": "B", "explanation": "''plant some flowers and a young tree.''"}, {"type": "choice", "q": "What will the tree give them in summer?", "options": ["Cool shade.", "Fruit.", "Flowers.", "Water."], "answer": "A", "explanation": "''it will give us cool shade in summer.''"}]'::jsonb, '[{"word": "shade", "cn": "树荫,阴凉"}]'::jsonb),
  ('6d760a20-f412-284d-339e-57e2bb8eef0b', 7, 'junior_fltrp', 'wy7A', 'U5', 'How to grow a seed', '将来时·种子成长', 'A: I put a seed in this small cup. What will happen to it?
B: If you give it water and sunlight, it will grow.
A: How long will it take?
B: In a few days, a small green leaf will come out.
A: Wonderful! Then it will become a real plant?
B: Yes. Plants are quiet, but they are full of power.', 'A:我昨天把一颗种子放进这小杯里,会怎样?B:只要给它水和阳光,它就会生长。A:要多久?B:过几天,一片小绿叶会长出来。A:太棒了!然后它会变成真正的植物?B:是的。植物很安静,却充满力量。', NULL, 'fable', 'dialogue', 31, 2, '[{"type": "choice", "q": "What does a seed need to grow?", "options": ["Only water.", "Cool shade.", "A big cup.", "Water and sunlight."], "answer": "D", "explanation": "''give it water and sunlight, it will grow.''"}, {"type": "choice", "q": "What does the boy learn about plants?", "options": ["They grow fast.", "They need no care.", "They are quiet but full of power.", "They are weak."], "answer": "C", "explanation": "结尾 ''they are full of power.''"}]'::jsonb, '[{"word": "seed", "cn": "种子"}, {"word": "sunlight", "cn": "阳光"}]'::jsonb),
  ('514cf8d3-af4d-a395-9aef-948fc0f1c197', 7, 'junior_fltrp', 'wy7A', 'U5', 'Save the tree', '将来时·保护树木', 'A: Look, this old tree by the road is dry. Will it die?
B: Not if we help it. Let''s give it some water.
A: Good idea. I''ll bring water every morning.
B: And I''ll ask more friends to help.
A: Together we will save it.
B: Yes. One tree gives homes to many birds.', 'A:看,路边这棵老树干枯了,它会死吗?B:如果我们帮它就不会。给它浇点水吧。A:好主意,我每天早上带水来。B:我再叫更多朋友帮忙。A:一起我们会救活它。B:是的,一棵树给许多鸟提供家。', NULL, 'fable', 'dialogue', 28, 1, '[{"type": "choice", "q": "How will they help the tree?", "options": ["Cut it down.", "Move it away.", "Paint it.", "Give it water."], "answer": "D", "explanation": "''Let''s give it some water.''"}, {"type": "choice", "q": "Why is the tree important?", "options": ["It gives homes to many birds.", "It is very old.", "It is by the road.", "It is tall."], "answer": "A", "explanation": "结尾:一棵树给许多鸟家。"}]'::jsonb, '[{"word": "dry", "cn": "干枯的"}, {"word": "die", "cn": "死亡"}]'::jsonb),
  ('685fa829-598e-f221-f532-682dde897b03', 7, 'junior_fltrp', 'wy7A', 'U5', 'My little seed', '独白·我的小种子', 'Today I put a small seed into the ground. It looks weak now, but it will become something great one day. First it will need water and sunlight. In a few days, a tiny green leaf will come out. Next spring, my seed will be a young tree. Birds will build their homes in it. In summer, it will give us cool shade. One small seed will change the whole garden.', '今天我把一颗小种子放进土里。它现在看着弱小,但我知道它会变得了不起。首先它需要水和阳光。几天后,一片嫩绿的叶子会长出。明年春天,我的种子会变成一棵小树。鸟儿会在里面筑巢。夏天它会给我们凉爽的树荫。一颗小种子会改变整个花园。', NULL, 'fable', 'passage', 39, 1, '[{"type": "choice", "q": "What will the seed need first?", "options": ["Birds.", "Cool shade.", "Water and sunlight.", "A garden."], "answer": "C", "explanation": "''First it will need water and sunlight.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["How to build a garden.", "How a small seed will grow and change the garden.", "Why birds like trees.", "How to water a plant."], "answer": "B", "explanation": "全文讲种子的未来与力量。"}]'::jsonb, '[{"word": "ground", "cn": "泥土,地面"}, {"word": "weak", "cn": "弱小的"}]'::jsonb),
  ('74581efa-998c-b192-826e-5a63d8029eeb', 7, 'junior_fltrp', 'wy7A', 'U5', 'Trees are our friends', '独白·树是朋友', 'Trees are quiet friends, and they help us in many ways. In summer, they give us cool shade. Birds and small animals will find homes in them. Trees also make the air fresh and clean. If we plant more trees, our city will become greener and more beautiful. Next month, our school will plant one hundred young trees. I will help too. Let''s take care of trees together.', '树是安静的朋友,它们在许多方面帮助我们。夏天给我们凉爽的树荫。鸟和小动物会在里面安家。树还让空气清新洁净。如果我们多种树,城市会更绿更美。下个月学校将种一百棵小树,我也会帮忙。让我们一起爱护树木。', NULL, 'fable', 'passage', 38, 2, '[{"type": "choice", "q": "How many trees will the school plant next month?", "options": ["Ten.", "Fifty.", "One hundred.", "One thousand."], "answer": "C", "explanation": "''plant one hundred young trees.''"}, {"type": "choice", "q": "What is the main idea of the passage?", "options": ["Summer is hot.", "Trees help us, so we should plant and protect them.", "Birds like trees.", "Cities are big."], "answer": "B", "explanation": "全文讲树的益处与保护。"}]'::jsonb, '[{"word": "fresh", "cn": "清新的"}, {"word": "green", "cn": "绿色的;多绿植的"}]'::jsonb),
  ('9943dbe6-0322-8802-d2e9-ac15a9968fc6', 7, 'junior_fltrp', 'wy7A', 'U5', 'Tree planting day', '通知·植树日', 'Good morning, students. Here is some news about our tree planting day. Next Saturday, we will plant young trees on the hill behind our school. Each class will get ten small trees. Please bring water and wear old clothes. We will meet at the school gate at eight in the morning. Let''s make our school greener together!', '同学们早上好。关于植树日的通知:下周六我们将在学校后山种小树。每班领十棵小树。请带水、穿旧衣服。我们上午八点在校门口集合。让我们一起让校园更绿!', NULL, 'fable', 'notice', 32, 1, '[{"type": "choice", "q": "How many trees will each class get?", "options": ["Ten.", "Five.", "Twenty.", "One hundred."], "answer": "A", "explanation": "''Each class will get ten small trees.''"}, {"type": "choice", "q": "What is the notice about?", "options": ["A sports day.", "A festival show.", "A club meeting.", "A tree planting day."], "answer": "D", "explanation": "通知主体=植树日。"}]'::jsonb, '[{"word": "hill", "cn": "小山"}, {"word": "gate", "cn": "大门"}]'::jsonb),
  ('08c65744-49a5-2826-edb7-9e3f827589e2', 7, 'junior_fltrp', 'wy7A', 'U6', 'At the zoo', '进行时·动物园', 'A: Look, Sam! The monkeys are playing in the tree.
B: Ha, they''re so funny. What is the panda doing?
A: It''s eating bamboo. It looks lazy and happy.
B: And those birds are flying over the lake.
A: I love the zoo. The animals are our friends.
B: Yes. Let''s always be kind to them.', 'A:看Sam!猴子们在树上玩。B:哈,好有趣。熊猫在做什么?A:它在吃竹子,看着又懒又开心。B:那些鸟在湖上飞。A:我爱动物园,动物是我们的朋友。B:是的,我们该善待它们。', NULL, 'fable', 'dialogue', 29, 1, '[{"type": "choice", "q": "What is the panda doing?", "options": ["Playing in the tree.", "Flying over the lake.", "Sleeping.", "Eating bamboo."], "answer": "D", "explanation": "''It''s eating bamboo.''"}, {"type": "choice", "q": "What do the two friends think about animals?", "options": ["They are dangerous.", "They are boring.", "They are our friends and we should be kind.", "They are noisy."], "answer": "C", "explanation": "结尾 ''The animals are our friends... be kind.''"}]'::jsonb, '[{"word": "monkeys", "cn": "猴子"}, {"word": "panda", "cn": "熊猫"}, {"word": "bamboo", "cn": "竹子"}]'::jsonb),
  ('b2ad0f15-f920-9dfc-6761-3f43531fed47', 7, 'junior_fltrp', 'wy7A', 'U6', 'My new pet', '进行时·宠物', 'A: You look happy today, Lily. What''s up?
B: I have a new pet cat! Look, she''s sleeping on my bag.
A: Oh, she''s so lovely. What is she doing now? She''s moving.
B: She''s waking up. She always wants milk in the morning.
A: Can I play with her?
B: Sure. But be gentle, she''s still a baby.', 'A:Lily你今天很开心,怎么了?B:我有只新宠物猫!看,她在我包上睡觉。A:哦好可爱,她现在在做什么?她在动。B:她在醒来,早上她总要喝奶。A:我能和她玩吗?B:当然,但轻点,她还是个宝宝。', NULL, 'fable', 'dialogue', 32, 2, '[{"type": "choice", "q": "What is the cat doing at first?", "options": ["Drinking milk.", "Sleeping on the bag.", "Playing with a ball.", "Eating fish."], "answer": "B", "explanation": "''she''s sleeping on my bag.''"}, {"type": "choice", "q": "Why does Lily ask her friend to be gentle?", "options": ["The cat is still a baby.", "The cat is angry.", "The cat is ill.", "The cat is hungry."], "answer": "A", "explanation": "''be gentle, she''s still a baby.''"}]'::jsonb, '[{"word": "pet", "cn": "宠物"}, {"word": "gentle", "cn": "温柔的"}]'::jsonb),
  ('160a13c9-0263-a497-6007-7fe0f40693b1', 7, 'junior_fltrp', 'wy7A', 'U6', 'Birds in the park', '进行时·公园的鸟', 'A: Listen! Some birds are singing in the park.
B: Yes, they sing every morning. It''s a lovely sound.
A: Look, that little bird is making a home in the tree.
B: Let''s keep quiet. We don''t want to make it afraid.
A: You''re right. Let''s just watch them.
B: Nature is beautiful, isn''t it?', 'A:听!公园里有鸟在唱歌。B:是啊,它们每天早上唱,声音真好听。A:看,那只小鸟在树上筑巢。B:我们该安静,不想吓着它。A:你说得对,我们就静静看着。B:大自然真美,对吧?', NULL, 'fable', 'dialogue', 30, 1, '[{"type": "choice", "q": "What is the little bird doing in the tree?", "options": ["Singing a song.", "Eating food.", "Sleeping.", "Making a home."], "answer": "D", "explanation": "''that little bird is making a home in the tree.''"}, {"type": "choice", "q": "Why do they keep quiet?", "options": ["They are tired.", "They don''t want to make the bird afraid.", "They are eating.", "They are reading."], "answer": "B", "explanation": "''We don''t want to make it afraid.''"}]'::jsonb, '[{"word": "nature", "cn": "大自然"}]'::jsonb),
  ('fa5b2e31-4a1a-825d-f546-00036c3c8109', 7, 'junior_fltrp', 'wy7A', 'U6', 'My dog Lucky', '独白·我的狗', 'I have a lovely dog. His name is Lucky. Right now he is lying by the door and waiting for me. Lucky is a fantastic friend. Every day after school, he runs to me and jumps happily. When I am sad, he sits beside me quietly. When I am happy, he plays with me in the garden. Look, he is looking at me now with his big eyes. I love my dog very much.', '我有一只可爱的狗,叫Lucky。此刻他正趴在门边等我。Lucky是个了不起的朋友。每天放学后,他跑向我、开心地跳。我难过时,他安静地坐在我身边;我开心时,他在花园里陪我玩。看,他正用大眼睛望着我。我很爱我的狗。', NULL, 'fable', 'passage', 40, 1, '[{"type": "choice", "q": "What is Lucky doing right now?", "options": ["Lying by the door and waiting.", "Running in the garden.", "Eating his food.", "Sleeping on the bed."], "answer": "A", "explanation": "''he is lying by the door and waiting for me.''"}, {"type": "choice", "q": "Why does the writer call Lucky a fantastic friend?", "options": ["He is big.", "He can run fast.", "He is always with the writer in every mood.", "He eats a lot."], "answer": "C", "explanation": "难过时陪伴、开心时玩耍 → 各种心情都在。"}]'::jsonb, '[{"word": "lying", "cn": "躺,趴(lie的进行式)"}, {"word": "beside", "cn": "在…旁边"}]'::jsonb),
  ('58bde51a-e541-3664-107b-bc57219658d5', 7, 'junior_fltrp', 'wy7A', 'U6', 'Animals are amazing', '独白·动物很奇妙', 'Animals are amazing, and each one is special. Look at the birds. They are flying high in the sky right now. In the river, fish are swimming quietly. On the farm, a mother hen is taking care of her babies. Animals help people in many ways, and they make our world lovely. Let''s be their friends and protect animals to keep them safe.', '动物很奇妙,每一种都特别。看那些鸟,此刻正在高空飞翔。河里,鱼儿静静游动。农场上,一只母鸡在照顾她的宝宝。动物在许多方面帮助人类,让我们的世界变得可爱。我们该做它们的朋友。让我们保护动物,让它们安全。', NULL, 'fable', 'passage', 35, 2, '[{"type": "choice", "q": "What are the fish doing in the river?", "options": ["Flying high.", "Taking care of babies.", "Eating grass.", "Swimming quietly."], "answer": "D", "explanation": "''fish are swimming quietly.''"}, {"type": "choice", "q": "What does the writer ask us to do?", "options": ["Catch more fish.", "Protect animals and keep them safe.", "Stay away from animals.", "Build more farms."], "answer": "B", "explanation": "结尾 ''Let''s protect animals and keep them safe.''"}]'::jsonb, '[{"word": "hen", "cn": "母鸡"}, {"word": "sky", "cn": "天空"}]'::jsonb),
  ('0659b062-815c-380a-1bb3-508108f00422', 7, 'junior_fltrp', 'wy7A', 'U6', 'Animal week', '通知·爱护动物周', 'Hello, students. Here is some news about our Animal Week. Next week, our school will learn about animals and how to protect them. On Monday, a teacher will show us photos of wild animals. On Wednesday, we will draw our favourite animals. On Friday, we will visit a small farm near the school. Come and be a friend to animals!', '同学们好,关于「爱护动物周」的通知:下周学校将学习动物以及如何保护它们。周一,一位老师会给我们看野生动物的照片。周三,我们画自己最喜欢的动物。周五,我们参观学校附近的一个小农场。来做动物的朋友吧!', NULL, 'fable', 'notice', 33, 1, '[{"type": "choice", "q": "What will students do on Friday?", "options": ["See photos.", "Draw animals.", "Visit a small farm.", "Watch a film."], "answer": "C", "explanation": "''On Friday, we will visit a small farm.''"}, {"type": "choice", "q": "What is the notice mainly about?", "options": ["An Animal Week to learn about and protect animals.", "A sports day.", "A music show.", "A maths test."], "answer": "A", "explanation": "通知主体=爱护动物周。"}]'::jsonb, '[{"word": "wild", "cn": "野生的"}, {"word": "farm", "cn": "农场"}]'::jsonb);

-- 断言
DO $$
DECLARE tot int; badq int; poll int; peru int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy7A';
  IF tot<>42 THEN RAISE EXCEPTION 'total=% 期望42', tot; END IF;
  SELECT count(*) INTO badq FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy7A' AND jsonb_array_length(questions)<>2;
  IF badq<>0 THEN RAISE EXCEPTION '题数≠2的篇=%', badq; END IF;
  SELECT count(*) INTO poll FROM public.junior_listening_exercises WHERE volume='wy7A' AND publisher<>'junior_fltrp';
  IF poll<>0 THEN RAISE EXCEPTION 'pep_polluted=%', poll; END IF;
  SELECT count(*) INTO peru FROM (SELECT unit FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy7A' GROUP BY unit HAVING count(*)<>6) t;
  IF peru<>0 THEN RAISE EXCEPTION '每单元≠6篇的单元数=%', peru; END IF;
  RAISE NOTICE 'OK: wy7A 听力 % 篇 · 7单元各6 · 每篇2题', tot;
END $$;

COMMIT;
SELECT unit, count(*) 篇, sum((audio_url IS NULL)::int) 待生成音频 FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy7A' GROUP BY unit ORDER BY min(difficulty);